-- Run after 002_knowledge_library.sql. Existing guide edits are preserved.
insert into public.guides(slug,category,title,description,minutes,steps,warning,source,published)
select slug,category,title,description,minutes,steps,warning,source,published
from jsonb_to_recordset($guides$[{"slug":"tv-picture-no-sound","category":"TV & video","title":"Picture, but no sound?","description":"Start with the audio path, not a factory reset.","minutes":4,"steps":["Lower the volume before changing sources. Check whether the TV, receiver, or soundbar is muted.","Using your normal remote, confirm that the intended speaker or audio output is selected. Make a note of its current setting first.","Try a familiar source or another app. Does the sound fail everywhere or only in one place?","Look at the accessible HDMI connections without moving heavy equipment. Note which ports are connected. Consult the model’s manual before changing ARC or eARC settings.","Write down which sources work and which do not. Share those observations with an expert if the issue persists."],"warning":"Do not open equipment, disconnect concealed wiring, or change installer menus. Stop if equipment smells hot or you see damage.","source":"https://www.sony.com/electronics/support","published":true},{"slug":"sonos-speaker-offline","category":"Audio","title":"When your speakers go quiet","description":"A few safe checks before you unplug everything.","minutes":5,"steps":["Confirm that the speaker has power and note its indicator light without interpreting it until you check the model’s documentation.","Check the volume and selected room in the manufacturer’s app.","Confirm your phone is on your home Wi-Fi, rather than a guest network. Do not share your Wi-Fi password here.","Check whether other devices can use the internet. This helps separate an audio issue from a network issue.","Record the speaker model, app error, and what changed recently. Consult the official support page for the exact model."],"warning":"Avoid factory resets: they may remove your system configuration and make recovery harder.","source":"https://support.sonos.com/","published":true},{"slug":"remote-not-responding","category":"Remotes","title":"A remote that won’t respond","description":"Find out whether it’s the remote or the system.","minutes":3,"steps":["Check the batteries or charging dock using the manufacturer’s instructions.","If your remote uses infrared, remove obvious obstructions between the remote and equipment.","Try one familiar function from the equipment’s physical controls, if accessible.","Note whether all buttons fail or only one room, activity, or device.","Record the remote model and any message on its screen. Use the exact model’s manual before attempting pairing."],"warning":"Do not reset or re-pair an installer-programmed remote without the original configuration or professional guidance.","source":"https://www.control4.com/help/","published":true},{"slug":"wifi-connected-no-internet","category":"Networking","title":"Wi-Fi connected. Internet missing.","description":"Work out where the connection breaks down.","minutes":5,"steps":["Try a familiar website on a second device connected to the same Wi-Fi.","Confirm you are on the intended home network. Guest networks may intentionally block AV devices.","Check your internet provider’s outage page using mobile data if available.","Observe the router and modem indicators. Compare them with the exact model’s official documentation.","Record which devices and rooms are affected. Avoid rebooting managed networking or equipment that supports alarms, care devices, or other critical systems."],"warning":"Do not change router settings, reset networking equipment, or share passwords. Managed networks may need the original installer.","source":"https://www.netgear.com/support/","published":true},{"slug":"smart-lights-not-responding","category":"Lighting","title":"Smart lights not responding?","description":"Separate a single light issue from a system issue.","minutes":4,"steps":["Use only the normal wall control and note whether the light responds.","Check whether the issue affects a single fixture, one room, or the whole home.","If the wall control works, try the manufacturer’s app from your home network.","Note any app error and whether the schedule or scene has changed.","Share these observations and the control model with an expert. Electrical faults need a qualified local professional."],"warning":"Never remove wall plates, open electrical panels, handle exposed wiring, or repeatedly operate a tripping breaker.","source":"https://support.lutron.com/","published":true},{"slug":"control-system-offline","category":"Automation","title":"Your control system says “offline”","description":"Understand what is reachable before making changes.","minutes":6,"steps":["Check whether other household devices can access the internet.","Observe the normal touch panel or app and write down the exact error.","Try another existing control, such as a normal remote or wall keypad.","Note whether the problem started after an outage, network change, or software update.","Identify the installed system and contact an expert or the original installer with your observations."],"warning":"Do not restart a control processor, reload programming, reset a hub, or update firmware without a verified recovery plan.","source":"https://www.crestron.com/Support","published":true}]$guides$::jsonb)
as g(slug text,category text,title text,description text,minutes integer,steps jsonb,warning text,source text,published boolean)
on conflict(slug) do nothing;
